export type DeliverablePluginPdas = {
  registry: typeof findRegistryPda;
  security: typeof findSecurityPda;
  position: typeof findPositionPda;
  premiumVault: typeof findPremiumVaultPda;
  optionMint: typeof findOptionMintPda;
  collateralVault: typeof findCollateralVaultPda;
  quoteVault: typeof findQuoteVaultPda;
  calendar: typeof findCalendarPda;
};

export type DeliverablePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function deliverableProgram() {
  return <T extends DeliverablePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { deliverable: DeliverablePlugin }> => {
    return extendClient(client, {
      deliverable: {
        accounts: {
          marketCalendar: addSelfFetchFunctions(
            client,
            getMarketCalendarCodec(),
          ),
          optionSeries: addSelfFetchFunctions(client, getOptionSeriesCodec()),
          registry: addSelfFetchFunctions(client, getRegistryCodec()),
          securityState: addSelfFetchFunctions(client, getSecurityStateCodec()),
          writerPosition: addSelfFetchFunctions(
            client,
            getWriterPositionCodec(),
          ),
        },
        instructions: {
          acknowledgeAdjustment: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcknowledgeAdjustmentInstruction(input),
            ),
          appendCalendarEntries: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAppendCalendarEntriesInstruction(input),
            ),
          attestHalt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAttestHaltInstructionAsync(input),
            ),
          claimPremium: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimPremiumInstructionAsync(input),
            ),
          createSeries: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateSeriesInstructionAsync(input),
            ),
          exercise: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExerciseInstructionAsync(input),
            ),
          initCalendar: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitCalendarInstructionAsync(input),
            ),
          initRegistry: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitRegistryInstructionAsync(input),
            ),
          openPosition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenPositionInstructionAsync(input),
            ),
          probeSecurity: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProbeSecurityInstructionAsync(input),
            ),
          probeSession: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProbeSessionInstruction(input),
            ),
          registerSecurity: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterSecurityInstructionAsync(input),
            ),
          setRegistryPaused: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetRegistryPausedInstructionAsync(input),
            ),
          settleExpired: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleExpiredInstructionAsync(input),
            ),
          syncSecurity: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSyncSecurityInstructionAsync(input),
            ),
          write: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWriteInstructionAsync(input),
            ),
        },
        pdas: {
          registry: findRegistryPda,
          security: findSecurityPda,
          position: findPositionPda,
          premiumVault: findPremiumVaultPda,
          optionMint: findOptionMintPda,
          collateralVault: findCollateralVaultPda,
          quoteVault: findQuoteVaultPda,
          calendar: findCalendarPda,
        },
        identifyAccount: identifyDeliverableAccount,
        identifyInstruction: identifyDeliverableInstruction,
        parseInstruction: parseDeliverableInstruction,
      } as DeliverablePlugin,
    });
  };
}
